#include <vector>

class Solution {
public:
    bool checkEqualPartitions(std::vector<int>& nums, long long target) {
        long double total = 1.0;
        for (int x : nums) total *= x;
        if (total != (long double)target * target) return false;

        int n = nums.size();
        for (int mask = 1; mask < (1 << n) - 1; ++mask) {
            long long curr = 1;
            bool ok = true;
            for (int i = 0; i < n; ++i) {
                if ((mask >> i) & 1) {
                    curr *= nums[i];
                    if (curr > target) {
                        ok = false;
                        break;
                    }
                }
            }
            if (ok && curr == target) return true;
        }

        return false;
    }
};

class Solution {
    public boolean checkEqualPartitions(int[] nums, long target) {
        double total = 1.0;
        for (int x : nums) total *= x;
        if (total != (double) target * target) return false;

        int n = nums.length;
        for (int mask = 1; mask < (1 << n) - 1; ++mask) {
            long curr = 1;
            boolean ok = true;
            for (int i = 0; i < n; ++i) {
                if (((mask >> i) & 1) != 0) {
                    curr *= nums[i];
                    if (curr > target) {
                        ok = false;
                        break;
                    }
                }
            }
            if (ok && curr == target) return true;
        }

        return false;
    }
}

