var checkEqualPartitions = function(nums, target) {
    let total = 1n;
    const targetBig = BigInt(target);
    for (const x of nums) {
        total *= BigInt(x);
    }
    if (total !== targetBig * targetBig) return false;

    const n = nums.length;
    for (let mask = 1; mask < (1 << n) - 1; ++mask) {
        let curr = 1n;
        let ok = true;
        for (let i = 0; i < n; ++i) {
            if ((mask >> i) & 1) {
                curr *= BigInt(nums[i]);
                if (curr > targetBig) {
                    ok = false;
                    break;
                }
            }
        }
        if (ok && curr === targetBig) return true;
    }

    return false;
};
